,'',0,'https://telethon.wruw.org/?wcccf=billing-fields',0,'wcccf','',0),(573,1,'2019-03-23 12:59:36','2019-03-23 12:59:36','','custom-fields','','publish','closed','closed','','custom-fields','','','2021-03-09 22:29:28','2021-03-10 03:29:28','',0,'https://telethon.wruw.org/?wcccf=custom-fields',0,'wcccf','',0),(623,1,'2019-03-23 22:31:37','2019-03-23 22:31:37','<!-- wp:code -->\n<pre class=\"wp-block-code\"><code>        &lt;div>\n            &lt;p>\n                Currently raised $&lt;?php echo $total ?>\n            &lt;/p>\n            &lt;!-- AddToAny BEGIN -->\n    &lt;div class=\"a2a_kit a2a_kit_size_32 a2a_default_style\">\n    &lt;a class=\"a2a_dd\" href=\"https://www.addtoany.com/share\">&lt;/a>\n    &lt;a class=\"a2a_button_facebook\">&lt;/a>\n    &lt;a class=\"a2a_button_twitter\">&lt;/a>\n    &lt;a class=\"a2a_button_email\">&lt;/a>\n    &lt;/div>\n    &lt;script async src=\"https://static.addtoany.com/menu/page.js\">&lt;/script>\n    &lt;!-- AddToAny END -->\n\n        &lt;/div></code></pre>\n<!-- /wp:code -->','A Different Drum','','inherit','closed','closed','','437-revision-v1','','','2019-03-23 22:31:37','2019-03-23 22:31:37','',437,'https://telethon.wruw.org/437-revision-v1/',0,'revision','',0),(628,1,'2019-03-23 22:40:50','2019-03-23 22:40:50','<!-- wp:code -->\n<pre class=\"wp-block-code\"><code></code></pre>\n<!-- /wp:code -->','A Different Drum','','inherit','closed','closed','','437-revision-v1','','','2019-03-23 22:40:50','2019-03-23 22:40:50','',437,'https://telethon.wruw.org/437-revision-v1/',0,'revision','',0),(631,1,'2019-03-23 22:48:15','2019-03-23 22:48:15','<!-- wp:image {\"id\":318} -->\n<figure class=\"wp-block-image\"><img src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/banner-1024x587.png\" alt=\"\" class=\"wp-image-318\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:html -->\n<div id=\"thermo\" class=\"thermometer horizontal\">\n\n        <div class=\"track\">\n            <div class=\"goal\">\n                <div class=\"amount\"> </div>\n            </div>\n            <div class=\"progress\">\n                <div class=\"amount\"></div>\n            </div>\n        </div>\n\n    </div>\n<script src=\"https://code.jquery.com/jquery-3.3.1.min.js\" integrity=\"sha256-FgpCb/KJQlLNfOu91ta32o/NMZxltwRo8QtmkMRdAu8=\" crossorigin=\"anonymous\"></script>\n<script>\n\nfunction formatCurrency(n, c, d, t) {\n    \"use strict\";\n\n    var s, i, j;\n\n    c = isNaN(c = Math.abs(c)) ? 2 : c;\n    d = d === undefined ? \".\" : d;\n    t = t === undefined ? \",\" : t;\n\n    s = n < 0 ? \"-\" : \"\";\n    i = parseInt(n = Math.abs(+n || 0).toFixed(c), 10) + \"\";\n    j = (j = i.length) > 3 ? j % 3 : 0;\n\n    return s + (j ? i.substr(0, j) + t : \"\") + i.substr(j).replace(/(\\d{3})(?=\\d)/g, \"$1\" + t) + (c ? d + Math.abs(n - i).toFixed(c).slice(2) : \"\");\n}\n\n\nfunction thermometer(id, goalAmount, progressAmount, animate) {\n    \"use strict\";\n\n    var $thermo = $(\"#\"+id),\n        $progress = $(\".progress\", $thermo),\n        $goal = $(\".goal\", $thermo),\n        percentageAmount,\n        isHorizontal = $thermo.hasClass(\"horizontal\"),\n        newCSS = {};\n\n    goalAmount = goalAmount || parseFloat( $goal.text() ),\n    progressAmount = progressAmount || parseFloat( $progress.text() ),\n    percentageAmount =  Math.min( Math.round(progressAmount / goalAmount * 1000) / 10, 100); //make sure we have 1 decimal point\n\n    //let\'s format the numbers and put them back in the DOM\n    $goal.find(\".amount\").text( \"$\" + formatCurrency( goalAmount ) );\n    $progress.find(\".amount\").text( \"$\" + formatCurrency( progressAmount ) );\n\n\n    //let\'s set the progress indicator\n    $progress.find(\".amount\").hide();\n\n    newCSS[ isHorizontal ? \"width\" : \"height\" ] = percentageAmount + \"%\";\n\n    if (animate !== false) {\n        $progress.animate( newCSS, 1200, function(){\n            $(this).find(\".amount\").fadeIn(500);\n        });\n    }\n    else {\n        $progress.css( newCSS );\n        $progress.find(\".amount\").fadeIn(500);\n    }\n}\n$(document).ready(function(){\n    thermometer(\"thermo\", 65000, total );\n});\n\n</script>\n<!-- /wp:html -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p style=\"text-align:center\">Welcome to the 2019 Telethon! Pick an item below.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table {\"align\":\"center\"} -->\n<table class=\"wp-block-table aligncenter\"><tbody><tr><td>\n</td><td><a href=\"https://telethon.wruw.org/product/donation-2/\">Donate a random amount</a></td><td></td></tr><tr><td><img class=\"wp-image-317\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/pullover_front.jpg\" alt=\"\"><br></td><td><a href=\"https://telethon.wruw.org/product/hoodie/\">2019 Telethon Hoodie</a></td><td>$100</td></tr><tr><td><img class=\"wp-image-316\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/FRONT.jpg\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/2019-telethon-shirt/\">2019 Telethon T-Shirt</a></td><td>$50</td></tr><tr><td><img class=\"wp-image-316\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/FRONT.jpg\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/2019-telethon-shirt-mystery-pack/\">2019 Telethon T-Shirt Pack</a></td><td>$100</td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/product/bottle-opener/\">Bottle Opener</a></td><td>$25</td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/product/10-cd-exploration-pack/\">10 CD Exploration Pack</a></td><td>$100</td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/product/4-cd-exploration-pack/\">4 CD Exploration Pack</a></td><td>$50<br></td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/index.php/product-category/show-time/\">Air Show Time</a></td><td>$100</td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/product/lunchbox/\">Lunch Box</a></td><td