text( \"$\" + formatCurrency( progressAmount ) );\n\n\n    //let\'s set the progress indicator\n    $progress.find(\".amount\").hide();\n\n    newCSS[ isHorizontal ? \"width\" : \"height\" ] = percentageAmount + \"%\";\n\n    if (animate !== false) {\n        $progress.animate( newCSS, 1200, function(){\n            $(this).find(\".amount\").fadeIn(500);\n        });\n    }\n    else {\n        $progress.css( newCSS );\n        $progress.find(\".amount\").fadeIn(500);\n    }\n}\n$(document).ready(function(){\n    thermometer(\"thermo\", 65000, total );\n});\n\n</script>\n<!-- /wp:html -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p style=\"text-align:center\">Welcome to the 2019 Telethon! Pick an item below.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table {\"align\":\"center\"} -->\n<table class=\"wp-block-table aligncenter\"><tbody><tr><td>\n</td><td><a href=\"https://telethon.wruw.org/product/donation-2/\">Donate a random amount</a></td><td></td></tr><tr><td><img class=\"wp-image-632\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/pullover_front_2.jpg\" alt=\"\"><a href=\"https://telethon.wruw.org/product/hoodie/\"></a></td><td><a href=\"https://telethon.wruw.org/product/hoodie/\">2019 Telethon Hoodie</a></td><td>$100</td></tr><tr><td><img class=\"wp-image-316\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/FRONT.jpg\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/2019-telethon-shirt/\">2019 Telethon T-Shirt</a></td><td>$50</td></tr><tr><td><img class=\"wp-image-640\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/FRONTx2.jpg\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/2019-telethon-shirt-mystery-pack/\">2019 Telethon T-Shirt Pack</a></td><td>$100</td></tr><tr><td><img class=\"wp-image-635\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/bottle_opener.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/bottle-opener/\">Bottle Opener</a></td><td>$25</td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/product/10-cd-exploration-pack/\">10 CD Exploration Pack</a></td><td>$100</td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/product/4-cd-exploration-pack/\">4 CD Exploration Pack</a></td><td>$50<br></td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/index.php/product-category/show-time/\">Air Show Time</a></td><td>$100</td></tr><tr><td></td><td><a href=\"https://telethon.wruw.org/product/lunchbox/\">Lunch Box</a></td><td>$75</td></tr><tr><td><img class=\"wp-image-173\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/hat_front.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/hat/\">Hat</a></td><td>$50</td></tr><tr><td><img class=\"wp-image-178\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/speaker.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/bluetooth-speaker/\">Bluetooth Speaker</a></td><td>$100</td></tr><tr><td><img class=\"wp-image-187\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/pint_glass-1.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/pint-glass/\">Pint Glass</a></td><td>$25</td></tr><tr><td><img class=\"wp-image-176\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/mug.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/mug/\">Mug</a></td><td>$50</td></tr><tr><td><img class=\"wp-image-181\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/tumbler.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/metal-tumbler/\">Metal Tumbler</a></td><td>$75</td></tr><tr><td><img class=\"wp-image-180\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/tiki_front.png\" alt=\"\"></td><td><a href=\"https: