          </div>\n            <div class=\"progress\">\n                <div class=\"amount\"></div>\n            </div>\n        </div>\n\n    </div>\n<script src=\"https://code.jquery.com/jquery-3.3.1.min.js\" integrity=\"sha256-FgpCb/KJQlLNfOu91ta32o/NMZxltwRo8QtmkMRdAu8=\" crossorigin=\"anonymous\"></script>\n<script>\n\nfunction formatCurrency(n, c, d, t) {\n    \"use strict\";\n\n    var s, i, j;\n\n    c = isNaN(c = Math.abs(c)) ? 2 : c;\n    d = d === undefined ? \".\" : d;\n    t = t === undefined ? \",\" : t;\n\n    s = n < 0 ? \"-\" : \"\";\n    i = parseInt(n = Math.abs(+n || 0).toFixed(c), 10) + \"\";\n    j = (j = i.length) > 3 ? j % 3 : 0;\n\n    return s + (j ? i.substr(0, j) + t : \"\") + i.substr(j).replace(/(\\d{3})(?=\\d)/g, \"$1\" + t) + (c ? d + Math.abs(n - i).toFixed(c).slice(2) : \"\");\n}\n\n\nfunction thermometer(id, goalAmount, progressAmount, animate) {\n    \"use strict\";\n\n    var $thermo = $(\"#\"+id),\n        $progress = $(\".progress\", $thermo),\n        $goal = $(\".goal\", $thermo),\n        percentageAmount,\n        isHorizontal = $thermo.hasClass(\"horizontal\"),\n        newCSS = {};\n\n    goalAmount = goalAmount || parseFloat( $goal.text() ),\n    progressAmount = progressAmount || parseFloat( $progress.text() ),\n    percentageAmount =  Math.min( Math.round(progressAmount / goalAmount * 1000) / 10, 100); //make sure we have 1 decimal point\n\n    //let\'s format the numbers and put them back in the DOM\n    $goal.find(\".amount\").text( \"$\" + formatCurrency( goalAmount ) );\n    $progress.find(\".amount\").text( \"$\" + formatCurrency( progressAmount ) );\n\n\n    //let\'s set the progress indicator\n    $progress.find(\".amount\").hide();\n\n    newCSS[ isHorizontal ? \"width\" : \"height\" ] = percentageAmount + \"%\";\n\n    if (animate !== false) {\n        $progress.animate( newCSS, 1200, function(){\n            $(this).find(\".amount\").fadeIn(500);\n        });\n    }\n    else {\n        $progress.css( newCSS );\n        $progress.find(\".amount\").fadeIn(500);\n    }\n}\n$(document).ready(function(){\n    thermometer(\"thermo\", 65000, total );\n});\n\n</script>\n<!-- /wp:html -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p style=\"text-align:center\">Welcome to the 2019 Telethon! Pick an item below.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table {\"align\":\"center\"} -->\n<table class=\"wp-block-table aligncenter\"><tbody><tr><td> <img class=\"wp-image-711\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/WRUW_ROUND-copy.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/donation-2/\">Donate a random amount</a></td><td></td></tr><tr><td><img class=\"wp-image-632\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/pullover_front_2.jpg\" alt=\"\"><a href=\"https://telethon.wruw.org/product/hoodie/\"></a></td><td><a href=\"https://telethon.wruw.org/product/hoodie/\">2019 Telethon Hoodie</a></td><td>$100</td></tr><tr><td><img class=\"wp-image-316\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/FRONT.jpg\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/2019-telethon-shirt/\">2019 Telethon T-Shirt</a></td><td>$50</td></tr><tr><td><img class=\"wp-image-640\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/FRONTx2.jpg\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/2019-telethon-shirt-mystery-pack/\">2019 Telethon T-Shirt Pack</a></td><td>$100</td></tr><tr><td><img class=\"wp-image-635\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/bottle_opener.png\" alt=\"\"></td><td><a href=\"https://telethon.wruw.org/product/bottle-opener/\">Bottle Opener</a></td><td>$25</td></tr><tr><td><img class=\"wp-image-712\" style=\"width: 150px;\" src=\"https://telethon.wruw.org/wp-content/uploads/2019/03/IMG_20190324_160627.jpg\" alt=\"\"></td><td><a href=\"https://te